import sqlite3

@contextmanager
def transaction(path):
    connection = sqlite3.connect(path)
    try:
        yield connection
        connection.commit()
    except BaseException:
        connection.rollback()
        raise
    finally:
        connection.close()

def write_value(path, key, value):
    with transaction(path) as connection:
        connection.execute('INSERT INTO entries(key, value) VALUES (?, ?)', (key, value))

