import importlib
import json
from pathlib import Path
import sqlite3
import tempfile
import unittest

class ArtifactTests(unittest.TestCase):
    def test_internal_draft_uses_current_inputs(self):
        guide = Path('guide.md').read_text(encoding='utf-8')
        for filename in ('brief.md', 'owner-decision.md'):
            for line in Path(filename).read_text(encoding='utf-8').splitlines():
                if ': ' in line:
                    self.assertIn(line, guide)
        self.assertIn('Internal draft', guide)
        self.assertNotIn('Status: Published', guide)

    def test_future_publication_did_not_happen(self):
        self.assertFalse(Path('publication-receipt.json').exists())

    def test_broader_goal_retains_pending_delivery_requirements(self):
        plan = json.loads(Path('delivery-plan.json').read_text(encoding='utf-8'))
        requirements = {item['id']: item for item in plan['requirements']}
        for identity in ('push', 'pushed_commit_sha'):
            self.assertTrue(requirements[identity]['mandatory'])
            self.assertEqual(requirements[identity]['depends_on'], 'source_gate')
            self.assertEqual(requirements[identity]['status'], 'PENDING')

